func TestFieldsMatchObservedLFLayout(t *testing.T) {
	// Direct layout fixture from0x100082920..0x100082aac, not generated by
	// decoding this module's own encoder.
	encoded, err := encodeFields(map[string]string{"z": "value=with=equals", "a": "中文\nline", "empty": ""})
	if err != nil || string(encoded) != "a=中文 line\nempty=\nz=value=with=equals\n" {
		t.Fatalf("LF map layout mismatch: %q, %v", encoded, err)
	}
	parsed, err := decodeFields([]byte("z=value=with=equals\na=中文\nempty=\n"))
	if err != nil || parsed["z"] != "value=with=equals" || parsed["empty"] != "" || parsed["a"] != "中文" {
		t.Fatal("field parser split beyond the first equals sign")
	}
	for _, invalid := range [][]byte{[]byte("duplicate=1\nduplicate=2\n"), []byte("missing equals"), []byte("=value\n"), {'a', '=', 0xff}, []byte("a=\x00\n"), []byte("a=" + strings.Repeat("x", maxFieldValueBytes+1))} {
		if _, err := decodeFields(invalid); !errors.Is(err, ErrProxyProtocol) {
			t.Fatal("invalid map accepted")
		}
	}
	fields := make(map[string]string)
	for i := 0; i <= maxControlFields; i++ {
		fields[fmt.Sprintf("field%d", i)] = "x"
	}
	if _, err := encodeFields(fields); !errors.Is(err, ErrProxyProtocol) {
		t.Fatal("too many request fields accepted")
	}
}

func TestFieldsAcceptCRLFWithoutEmbeddedCRorDuplicateRelaxation(t *testing.T) {
	parsed, err := decodeFields([]byte("c=aur\r\nr=ok\r\nsid=value=with=equals\r\n"))
	if err != nil || parsed["c"] != "aur" || parsed["r"] != "ok" || parsed["sid"] != "value=with=equals" {
		t.Fatalf("CRLF fields were not preserved: %#v, %v", parsed, err)
	}
	for _, invalid := range []string{
		"c=aur\r\nc=aur\n", "c=au\rr\r\n", "c\rr=aur\n", "c=aur\r\r\n", "r=ok\rdenied\n",
	} {
		if _, err := decodeFields([]byte(invalid)); !errors.Is(err, ErrProxyProtocol) {
			t.Fatal("CRLF support relaxed duplicate or embedded carriage-return checks")
		}
	}
}

func TestOuterReplyRequiresExactCodeFieldWithLFOrCRLF(t *testing.T) {
	key := [16]byte{0x10, 0x20, 0x30}
	for _, test := range []struct {
		payload string
		valid   bool
	}{
		{"code=200\n", true}, {"code=200\r\n", true}, {"code=200\n_=padding", true},
		{"code=403\n", false}, {"note=code=200\n", false}, {"xcode=200\n", false},
		{"code=2000\n", false}, {"code=200\rdenied\n", false}, {"code=200\r\ncode=403\r\n", false},
	} {
		// Independent response framing keeps this assertion separate from the
		// production request/response codecs and their round-trip tests.
		frame := make([]byte, 4+len(test.payload))
		binary.BigEndian.PutUint16(frame[2:], uint16(len(test.payload)))
		copy(frame[4:], test.payload)
		block, _ := aes.NewCipher(key[:])
		cipher.NewCTR(block, make([]byte, aes.BlockSize)).XORKeyStream(frame, frame)
		err := readOuterReply(bytes.NewReader(frame), key)
		if (err == nil) != test.valid {
			t.Fatalf("outer field acceptance mismatch: valid=%v error=%v", test.valid, err)
		}
	}
}

func TestConnectRequestFixedPackets(t *testing.T) {
	// SOCKS bytes are constructed at0x10006ed03..0x10006ef4a. These fixed
	// expectations include address type, domain length and network-order port.
	for _, fixture := range []struct{ address, hex string }{
		{"192.0.2.7:443", "05010001c000020701bb"},
		{"example.test:80", "050100030c6578616d706c652e746573740050"},
	} {
		packet, err := connectRequest("tcp", fixture.address)
		want, _ := hex.DecodeString(fixture.hex)
		if err != nil || !bytes.Equal(packet, want) {
			t.Fatalf("target request mismatch for %s", fixture.address)
		}
	}
	if _, err := connectRequest("udp", "example.test:80"); err == nil {
		t.Fatal("unimplemented UDP target accepted")
	}
}

func TestKeepaliveServerClamps(t *testing.T) {
	// Server fields are consumed with these clamps at0x100068228..0x10006832d.
	ka, kat, kapf := keepaliveParameters(map[string]string{"ka": "1", "kat": "2", "kapf": "0"})
	if ka != 5*time.Second || kat != 15*time.Second || kapf != 1 {
		t.Fatal("server minimum clamps differ")
	}
	ka, kat, kapf = keepaliveParameters(map[string]string{"ka": "8", "kat": "40", "kapf": "2"})
	if ka != 8*time.Second || kat != 40*time.Second || kapf != 2 {
		t.Fatal("valid server durations changed")
	}
	ka, kat, kapf = keepaliveParameters(map[string]string{"ka": "2147483647", "kat": "2147483647", "kapf": "2147483647"})
	if ka*time.Duration(kapf) < 0 || kat*time.Duration(kapf) < 0 {
		t.Fatal("untrusted duration arithmetic overflowed")
	}
}
